import type { Spec } from './registry.ts'

export type Config = Record<string, Spec> | Spec

export function defineConfig<const T extends Record<string, Spec>>(config: T): T
export function defineConfig<const T extends Record<string, Spec>>(config: () => T): T
export function defineConfig<const T extends Record<string, Spec>>(config: () => Promise<T>): Promise<T>
export function defineConfig<const T extends Spec>(config: T): T
export function defineConfig<const T extends Spec>(config: () => T): T
export function defineConfig<const T extends Spec>(config: () => Promise<T>): Promise<T>
export function defineConfig<const T extends Spec>(config: T): T {
  return config
}
